/*
 * Adds the site's navigation to the exported game page.
 *
 * Injected via the export preset's `html/head_include`. The exported
 * index.html is regenerated by every build, so it cannot be edited directly —
 * and a full custom shell would have to be kept in step with whatever Godot's
 * own template does next. This only adds to the page it finds.
 *
 * The bar exists because the game on its own is a dead end: once you start
 * playing there is no way back to the site, and Escape+H returns you to the
 * game's title screen, not to the rest of the pages.
 */
(function () {
  "use strict";

  function build() {
    var canvas = document.getElementById("canvas");
    if (!canvas || document.getElementById("play-nav")) {
      return;
    }

    var nav = document.createElement("nav");
    nav.id = "play-nav";
    nav.innerHTML =
      '<a href="/">&larr; Chuckie Egg</a>' +
      '<a href="/scores">High scores</a>' +
      '<span class="hint"><kbd>S</kbd> start' +
      ' &middot; <kbd>H</kbd> hold' +
      ' &middot; <kbd>Escape</kbd>+<kbd>H</kbd> quit to title</span>';

    var stage = document.createElement("div");
    stage.id = "play-stage";

    // Move the canvas rather than rebuild it: the engine has already taken a
    // reference to this element, and replacing it would leave it rendering
    // into an orphan.
    canvas.parentNode.insertBefore(stage, canvas);
    stage.appendChild(canvas);
    document.body.insertBefore(nav, stage);

    // The shell focuses the canvas on start, but clicking a link takes focus
    // away and the keyboard stops reaching the game. Give it back on any click
    // in the stage.
    stage.addEventListener("mousedown", function () {
      canvas.focus();
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", build);
  } else {
    build();
  }
})();
